const BY_KEY: ReadonlyMap<string, GmCommand> = new Map(
  GM_COMMANDS.flatMap((c) => [c.name, ...c.aliases].map((k) => [k.toLowerCase(), c] as const)),
);

/** Case-insensitive lookup of a command token (no leading slash); `undefined` when unknown (23 §3.3). */
export function findCommand(token: string): GmCommand | undefined {
  return BY_KEY.get(token.toLowerCase());
}

/** The commands an `authority` byte may use: the auto-complete list of 23 §3.10 (browser-handled rows included). */
export function visibleCommands(authority: number): GmCommand[] {
  return GM_COMMANDS.filter((c) => authority >= c.minAuth);
}
